server {
  root /var/www/myapp/public; # Not /var/www/myapp/

  # Block sensitive files as defense-in-depth
  location ~* /(composer\.(json|lock)|Makefile|\.env) {
    deny all;
    return 404;
  }
}

location ~* /\.env {
  deny all;
  return 404;
}

# Also block hidden files in general
location ~ /\. {
  deny all;
  return 404;
}

// BAD: whatever the URL returns runs immediately, unreviewed
// "postinstall": "curl -sL https://example.com/setup.sh | bash"

// GOOD: local script downloads to a file, checks it, then runs it
